    public List<TreeNode> findDuplicateSubtrees(TreeNode root) {
        List<TreeNode> result = new ArrayList<>();
        if (root == null) {
            return result;
        }
        // 记录子树
        List<String> subTrees = new ArrayList<>();
        dfs(root, subTrees, result);
        return result;
    }

    private String dfs(TreeNode node, List<String> subTrees, List<TreeNode> result) {
        if (node == null) {
            return "";
        }
        String left = dfs(node.left, subTrees, result);
        String right = dfs(node.right, subTrees, result);
        String subTree = left + node.val + right;
        if (subTrees.contains(subTree)) {
            result.add(node);
        }
        subTrees.add(subTree);
        return subTree;
    }

